functions.ensure_running:
def ensure_running(self, *, timeout=30.0):
        deadline = self.monotonic() + timeout
        result = self.adapter.start()
        while result['state'] in {'starting', 'degraded', 'unknown'}:
            if result.get('reason') not in {'STARTUP_PENDING', 'CONCURRENT_START',
                    'SERVICE_UNREACHABLE', 'INSTANCE_OWNERSHIP_UNCONFIRMED',
                    'INSTANCE_METADATA_UNAVAILABLE', 'SUPERVISOR_PENDING', 'SUPERVISOR_LAST_ATTEMPT_FAILED'}:
                return result
            # A concurrent publisher/Windows file-sharing window can prevent
            # reading owner metadata. Re-inspect within this deadline; never
            # call start again or infer absence from an unreadable record.
            remaining = deadline - self.monotonic()
            if remaining <= 0:
                return {**result, 'wait_timed_out': True,
                    'next_action': 'Query status again. This timeout did not stop or restart the service.'}
            self.sleep(min(.1, remaining))
            result = self.adapter.inspect(timeout=min(1.0, max(.01, deadline - self.monotonic())))
        return result

functions.request_stop:
def request_stop(self, current, *, timeout, force=False):
        if type(force) is not bool:
            raise ValueError('Force must be a boolean.')
        pending = current.get('reason') in {'SUPERVISOR_PENDING', 'SUPERVISOR_LAST_ATTEMPT_FAILED'} and not current.get('generation')
        if force:
            actual = self._inspect_process(timeout=min(.5, timeout))
            if (not current.get('generation') or actual.get('generation') != current['generation']
                    or actual.get('instance_id') != current.get('instance_id')):
                return {**actual, 'state': 'failed', 'reason': 'INSTANCE_CHANGED',
                    'next_action': 'Inspect the current generation; no force was requested.'}
        if current['state'] not in {'ready', 'stopping'} and not pending:
            return current
        if (self.home / INSTALLATION_NAME).exists():
            try:
                with launch_exclusion(self.home, self.database):
                    actual = self._inspect_process(timeout=min(.5, timeout))
                    if (actual.get('generation') != current.get('generation')
                            or (pending and actual['state'] != 'stopped')):
                        return {**actual, 'state': 'failed', 'reason': 'INSTANCE_CHANGED',
                            'next_action': 'Observe the current generation before requesting another stop.'}
                    self.installation.begin_stop(current.get('generation'))
                    if pending:
                        return {**current, 'state': 'stopping', 'shutdown': {'state': 'DRAINED', 'resources': []},
                            'reason': 'STARTUP_SUPPRESSED', 'next_action': 'Wait for the scheduled entry to observe the stop latch and exit.'}
            except LockBusy:
                return {**current, 'reason': 'CONCURRENT_LIFECYCLE',
                    'next_action': 'Repeat stop after the current lifecycle operation completes.'}
            except (OSError, ValueError, ImportError) as error:
                return installation_failure(current, error)
        address = '[::1]' if self.host in {'::', '::1'} else '127.0.0.1'
        body = {'instance_id': current['instance_id'],
                'generation': current['generation'], 'timeout_seconds': float(timeout)}
        if force:
            body['force'] = True
        request = Request(f'http://{address}:{self.port}/api/v1/service/stop',
            data=json.dumps(body).encode(),
            headers={'Content-Type': 'application/json'}, method='POST')
        try:
            with build_opener(ProxyHandler({}), NoRedirect()).open(request, timeout=max(.01, timeout)) as response:
                raw = response.read(32769)
                if len(raw) > 32768:
                    raise ValueError('Oversized shutdown response')
                result = json.loads(raw)
                data = result['data']
                if (result.get('ok') is not True or data['instance_id'] != current['instance_id']
                        or data['generation'] != current['generation']):
                    raise ValueError('Shutdown identity mismatch')
                report = data['shutdown']
        except HTTPError as error:
            # An explicit canonical refusal is not a lost response. Never
            # print peer text, malformed bodies or URLs from an exception.
            reason = None
            try:
                raw = error.read(32769)
                if len(raw) <= 32768:
                    envelope = json.loads(raw)
                    refusal = envelope.get('error', {})
                    code = refusal.get('code')
                    details = refusal.get('details') or {}
                    if error.code in {400, 401, 403, 409, 422} and code in {
                            'CONFLICT', 'INSTANCE_MISMATCH', 'AUTH_FAILED', 'PERMISSION_DENIED',
                            'VALIDATION_ERROR', 'INVALID_TRANSITION'}:
                        reason = ('DRAIN_DECISION_NOT_AVAILABLE'
                            if details.get('reason') == 'DRAIN_DECISION_NOT_AVAILABLE'
                            else 'SHUTDOWN_REQUEST_REFUSED')
            except (OSError, ValueError, TypeError, AttributeError):
                pass
            if reason:
                return {**current, 'state': 'failed', 'reason': reason,
                        'next_action': 'Inspect the current drain before another explicit decision.'}
            report = {'state': 'UNCONFIRMED', 'resources': []}
        except (OSError, ValueError, KeyError, TypeError):
            report = {'state': 'UNCONFIRMED', 'resources': []}
        return {**current, 'state': 'stopping', 'shutdown': report,
            'reason': 'RUNTIME_DRAINING', 'next_action': (
                'Observe the same generation; a force decision was submitted and its outcome must be confirmed.' if force else
                'Observe the same generation; no force or restart was requested.')}

functions.inspect_local_server:
def inspect_local_server(*, home: Path, database: Path, host: str, port: int,
                         timeout: float = 2.0) -> dict:
    home, database = home.resolve(), database.resolve()
    result = {'component': 'server', 'instance_id': server_instance_id(home, database),
              'installed_version': version('okto-nexus'), 'active_version': None,
              'generation': None, 'state': 'unknown', 'ready_for_queries': False,
              'work_state': 'not_checked', 'reason': None, 'next_action': None,
              'effective_configuration': {'home': str(home), 'database': str(database),
                                          'bind_host': host, 'port': port}}
    guards = [_held(home / 'nexus.serve.guard'),
              _held(database.with_name(database.name + '.serve.guard'))]
    try:
        metadata = json.loads((home / 'nexus.serve.lock').read_text(encoding='utf-8'))
        if not isinstance(metadata, dict):
            metadata = {}
    except FileNotFoundError:
        metadata = {}
    except (OSError, ValueError):
        return {**result, 'reason': 'INSTANCE_METADATA_UNAVAILABLE',
                'next_action': 'Inspect permissions and the existing foreground instance.'}
    if guards == [False, False] and (not metadata or metadata.get('lock_version') == 2):
        return {**result, 'state': 'stopped', 'reason': 'NO_SERVICE_OWNER',
                'next_action': 'Start the configured instance explicitly. Runtime work has not been inspected.'}
    if guards != [True, True]:
        return {**result, 'reason': 'INSTANCE_OWNERSHIP_UNCONFIRMED',
                'next_action': 'Inspect the existing owner; do not start a competing instance.'}
    if host not in {'127.0.0.1', 'localhost', '0.0.0.0', '::', '::1'}:
        return {**result, 'reason': 'LOCAL_CONTROL_UNAVAILABLE',
                'next_action': 'This bind has no loopback control address; inspect the foreground service.'}
    address = '[::1]' if host in {'::', '::1'} else '127.0.0.1'
    endpoint = f'http://{address}:{port}/api/v1/service'
    try:
        opener = build_opener(ProxyHandler({}), NoRedirect())
        with opener.open(endpoint, timeout=timeout) as response:
            # No unbounded or secret-bearing body is surfaced in a diagnostic.
            payload = response.read(32769)
            if len(payload) > 32768:
                raise ValueError('Oversized readiness response')
            document = json.loads(payload)
            data = document.get('data') if document.get('ok') is True else None
            if not isinstance(data, dict):
                raise ValueError('Invalid readiness envelope')
    except (HTTPError, URLError, TimeoutError, OSError, ValueError, AttributeError):
        return {**result, 'state': 'degraded', 'reason': 'SERVICE_UNREACHABLE',
                'next_action': 'Inspect startup/transport diagnostics for this instance; no process was started.'}
    # A child holds the guards before publishing metadata; startup may complete
    # while this HTTP request is in flight. Re-correlate after the response so
    # an initial absent/old diagnostic record cannot reject the actual owner.
    previous = metadata
    try:
        metadata = json.loads((home / 'nexus.serve.lock').read_text(encoding='utf-8'))
    except (OSError, ValueError):
        metadata = {}
    if not isinstance(metadata, dict):
        metadata = {}
    after = [_held(home / 'nexus.serve.guard'),
             _held(database.with_name(database.name + '.serve.guard'))]
    if after != [True, True] or not metadata.get('generation'):
        return {**result, 'reason': 'INSTANCE_OWNERSHIP_UNCONFIRMED',
            'next_action': 'The owner changed during inspection; observe the same initialization again.'}
    if (metadata != previous and (data.get('generation') != metadata.get('generation')
                                 or data.get('pid') != metadata.get('pid'))):
        return {**result, 'reason': 'INSTANCE_OWNERSHIP_UNCONFIRMED',
            'next_action': 'The owner changed during inspection; observe the current generation again.'}
    if (data.get('instance_id') != result['instance_id'] or not metadata.get('generation')
            or data.get('generation') != metadata['generation']
            or data.get('pid') != metadata.get('pid')
            or data.get('component') != 'server'):
        return {**result, 'state': 'failed', 'reason': 'INSTANCE_MISMATCH',
                'next_action': 'The endpoint does not prove ownership of this configured instance.'}
    if (data.get('protocol_revision') != SERVICE_PROTOCOL_REVISION
            or data.get('active_version') != result['installed_version']):
        return {**result, 'state': 'degraded', 'active_version': data.get('active_version'),
                'generation': data.get('generation'), 'pid': data.get('pid'),
                'reason': 'VERSION_INCOMPATIBLE',
                'next_action': 'Review active and installed versions; do not interrupt or upgrade implicitly.'}
    allowed = {'component', 'instance_id', 'generation', 'active_version', 'pid', 'supervisor',
               'state', 'ready_for_queries', 'storage_initialized', 'admission',
               'reason', 'next_action', 'protocol_revision', 'shutdown'}
    if (data.get('state') not in {'starting', 'ready', 'degraded', 'stopping', 'failed'}
            or type(data.get('ready_for_queries')) is not bool):
        return {**result, 'state': 'failed', 'reason': 'INVALID_READINESS',
                'next_action': 'Inspect the active service protocol.'}
    return {**result, **{key: data[key] for key in allowed if key in data}}
